    75	static int velawear_write_all(const char *buffer, size_t length)
    76	{
    77	  while (length > 0)
    78	    {
    79	      size_t request = length > 64 ? 64 : length;
    80	      ssize_t written = write(STDOUT_FILENO, buffer, request);
    81	
    82	      if (written > 0)
    83	        {
    84	          buffer += written;
    85	          length -= written;
    86	          usleep(10000);
    87	        }
    88	      else if (written < 0 && (errno == EINTR || errno == EAGAIN))
    89	        {
    90	          usleep(1000);
    91	        }
    92	      else
    93	        {
    94	          return -1;
    95	        }
    96	    }
    97	
    98	  return 0;
    99	}
