   101	static int velawear_dump_lcd_capture(void)
   102	{
   103	  static const char alphabet[] =
   104	    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
   105	  const size_t width = 390;
   106	  const size_t height = 100;
   107	  const size_t frame_bytes = width * height * 2;
   108	  uint8_t *snapshot;
   109	  char encoded[4];
   110	  char output[1024];
   111	  size_t offset;
   112	  size_t encoded_len;
   113	  size_t output_len = 0;
   114	  size_t line_len = 0;
   115	  size_t i;
   116	  int ret;
   117	
   118	  snapshot = malloc(frame_bytes);
   119	  if (snapshot == NULL)
   120	    {
   121	      return -ENOMEM;
   122	    }
   123	
   124	  ret = sf32lb_lcd_copy_capture(snapshot, frame_bytes);
   125	  if (ret < 0)
   126	    {
   127	      printf("[LCDSHADOW] capture unavailable: %d\n", ret);
   128	      free(snapshot);
   129	      return ret;
   130	    }
   131	
   132	  printf("LCDSHADOW_BEGIN %u %u %u %u %zu\n",
   133	         (unsigned int)width, (unsigned int)height, 16U,
   134	         (unsigned int)(width * 2), frame_bytes);
   135	
   136	  for (offset = 0; offset < frame_bytes; offset += 3)
   137	    {
   138	      size_t remaining = frame_bytes - offset;
   139	      uint32_t a = snapshot[offset];
   140	      uint32_t b = remaining > 1 ? snapshot[offset + 1] : 0;
   141	      uint32_t c = remaining > 2 ? snapshot[offset + 2] : 0;
   142	
   143	      encoded_len = 0;
   144	      encoded[encoded_len++] = alphabet[(a >> 2) & 0x3f];
   145	      encoded[encoded_len++] = alphabet[((a & 0x03) << 4) |
   146	                                        ((b >> 4) & 0x0f)];
   147	      encoded[encoded_len++] = remaining > 1 ?
   148	        alphabet[((b & 0x0f) << 2) | ((c >> 6) & 0x03)] : '=';
   149	      encoded[encoded_len++] = remaining > 2 ? alphabet[c & 0x3f] : '=';
   150	
   151	      for (i = 0; i < encoded_len; i++)
   152	        {
   153	          output[output_len++] = encoded[i];
   154	          line_len++;
   155	          if (line_len == 72)
   156	            {
   157	              output[output_len++] = '\n';
   158	              line_len = 0;
   159	            }
   160	
   161	          if (output_len >= sizeof(output) - 4)
   162	            {
   163	              if (velawear_write_all(output, output_len) < 0)
   164	                {
   165	                  free(snapshot);
   166	                  return -EIO;
   167	                }
   168	
   169	              output_len = 0;
   170	            }
   171	        }
   172	    }
   173	
   174	  if (line_len != 0)
   175	    {
   176	      output[output_len++] = '\n';
   177	    }
   178	  if (output_len != 0 && velawear_write_all(output, output_len) < 0)
   179	    {
   180	      free(snapshot);
   181	      return -EIO;
   182	    }
   183	
   184	  printf("LCDSHADOW_END\n");
   185	  free(snapshot);
   186	  return 0;
   187	}
