    76	int main(int argc, char *argv[])
    77	{
    78	  int ret;
    79	  bool falltest = argc > 1 && strcmp(argv[1], "falltest") == 0;
    80	
    81	  if (argc > 1 && strcmp(argv[1], "audio") == 0)
    82	    {
    83	      return velawear_audio_hw_test();
    84	    }
    85	
    86	  if (argc > 1 && strcmp(argv[1], "beep") == 0)
    87	    {
    88	      return velawear_speaker_alert(500, 0);
    89	    }
    90	
    91	  if (argc > 1 && strcmp(argv[1], "music") == 0)
    92	    {
    93	      return velawear_music_hw_test();
    94	    }
    95	
    96	  syslog(LOG_INFO, "[VelaWear] Agent starting...\n");
    97	  if (argc > 1 && strcmp(argv[1], "mic") == 0)
    98	    {
    99	      return velawear_mic_hw_test();
   100	    }
   101	
   102	  /* Initialize agent structure */
   103	
   104	  memset(&g_agent, 0, sizeof(velawear_agent_t));
   105	  g_agent.running = false;
   106	  g_agent.watchdog_fd = -1;
   107	  g_agent.power_mode = VELAWEAR_POWER_IDLE;
   108	  g_agent.operation_mode = VELAWEAR_MODE_ONLINE;
   109	  g_agent.imu_available = false;
   110	  g_agent.audio_available = false;
   111	  g_agent.ble_available = false;
   112	
   113	  /* Set up signal handler */
   114	
   115	  signal(SIGTERM, velawear_signal_handler);
   116	  signal(SIGINT, velawear_signal_handler);
   117	
   118	  /* Initialize subsystems */
   119	
   120	  ret = velawear_init(&g_agent);
   121	  if (ret < 0)
   122	    {
   123	      syslog(LOG_ERR, "[VelaWear] Initialization failed: %d\n", ret);
   124	      return EXIT_FAILURE;
   125	    }
   126	
   127	  /* Start the agent */
   128	
   129	  ret = velawear_start(&g_agent);
   130	  if (ret < 0)
   131	    {
   132	      syslog(LOG_ERR, "[VelaWear] Start failed: %d\n", ret);
   133	      velawear_cleanup(&g_agent);
   134	      return EXIT_FAILURE;
   135	    }
   136	
   137	  syslog(LOG_INFO, "[VelaWear] Agent started successfully\n");
   138	
   139	  /* Main event loop: block waiting for events.  IMU sampling runs in its
   140	   * producer thread so this task remains the single queue consumer. */
   141	  {
   142	    bool falltest_sent = false;
   143	    uint32_t last_activity_ms = velawear_now_ms();
   144	
   145	    while (g_agent.running)
   146	      {
   147	        velawear_event_t event;
   148	        int event_ret;
   149	        int wait_ms;
   150	
   151	        if (g_agent.power_mode == VELAWEAR_POWER_DEEP_SLEEP)
   152	          {
   153	            wait_ms = 100;
   154	          }
   155	        else if (g_agent.power_mode == VELAWEAR_POWER_LIGHT_SLEEP)
   156	          {
   157	            wait_ms = 100;
   158	          }
   159	        else if (g_agent.power_mode == VELAWEAR_POWER_IDLE)
   160	          {
   161	            wait_ms = 100;
   162	          }
   163	        else
   164	          {
   165	            wait_ms = 100;
   166	          }
   167	
   168	        if (falltest && !falltest_sent)
   169	          {
   170	            memset(&event, 0, sizeof(event));
   171	            event.type = VELAWEAR_EVENT_FALL;
   172	            event.priority = VELAWEAR_PRIORITY_CRITICAL;
   173	            if (event_manager_push(&g_agent.events, &event) < 0)
   174	              {
   175	                syslog(LOG_ERR,
   176	                       "[VelaWear] Fall self-test event enqueue failed\n");
   177	              }
   178	            else
   179	              {
   180	                syslog(LOG_INFO,
   181	                       "[VelaWear] Fall self-test event queued\n");
   182	              }
   183	            falltest_sent = true;
   184	          }
   185	
   186	        event_ret = event_manager_pop(&g_agent.events, &event, wait_ms);
   187	        if (event_ret == VELAWEAR_OK)
   188	          {
   189	            if (event.type != VELAWEAR_EVENT_MOTION)
   190	              {
   191	                last_activity_ms = velawear_now_ms();
   192	                velawear_set_power_mode(&g_agent, VELAWEAR_POWER_ACTIVE,
   193	                                        "event received");
   194	              }
   195	            event_ret = event_manager_dispatch(&g_agent.events, &event);
   196	            if (event_ret < 0)
   197	              {
   198	                syslog(LOG_WARNING,
   199	                       "[VelaWear] Event dispatch failed: %d\n", event_ret);
   200	              }
   201	            else if (falltest && event.type == VELAWEAR_EVENT_FALL)
   202	              {
   203	                /* Give action worker and main-thread display handoff time to run. */
   204	                for (int i = 0; i < 10; i++)
   205	                  {
   206	                    usleep(100000);
   207	                    display_manager_tick(&g_agent.display);
   208	                  }
   209	                g_agent.running = false;
   210	              }
   211	          }
   212	        else if (event_ret != VELAWEAR_ERR_TIMEOUT)
   213	          {
   214	          syslog(LOG_WARNING,
   215	                 "[VelaWear] Event wait failed: %d\n", event_ret);
   216	          }
   217	
   218	        velawear_buttons_poll(&g_agent.display, &last_activity_ms);
   219	
   220	        {
   221	          uint32_t idle_ms = velawear_now_ms() - last_activity_ms;
   222	
   223	          if (display_manager_is_busy(&g_agent.display))
   224	            {
   225	              /* Keep interactive apps and active tests awake. */
   226	              last_activity_ms = velawear_now_ms();
   227	            }
   228	          else if (idle_ms >= 60000)
   229	            {
   230	              velawear_set_power_mode(&g_agent, VELAWEAR_POWER_DEEP_SLEEP,
   231	                                      "60 seconds without user event");
   232	            }
   233	          else if (idle_ms >= 30000)
   234	            {
   235	              velawear_set_power_mode(&g_agent, VELAWEAR_POWER_LIGHT_SLEEP,
   236	                                      "30 seconds without user event");
   237	            }
   238	          else if (idle_ms >= 10000)
   239	            {
   240	              velawear_set_power_mode(&g_agent, VELAWEAR_POWER_IDLE,
   241	                                      "10 seconds without user event");
   242	            }
   243	        }
   244	
   245	        /* Keep LVGL timers and touch input alive so sleep can be woken. */
   246	        display_manager_tick(&g_agent.display);
   247	        velawear_watchdog_ping(&g_agent);
   248	      }
   249	  }
   250	
   251	  /* Cleanup */
   252	
   253	  velawear_cleanup(&g_agent);
   254	  syslog(LOG_INFO, "[VelaWear] Agent stopped\n");
   255	
   256	  return EXIT_SUCCESS;
   257	}
