    47	
    48	static ssize_t velawear_ble_read_status(struct bt_conn *conn,
    49	                                        const struct bt_gatt_attr *attr,
    50	                                        void *buf, uint16_t len,
    51	                                        uint16_t offset)
    52	{
    53	  uint8_t value[3];
    54	
    55	  (void)attr;
    56	  pthread_mutex_lock(&g_lock);
    57	  value[0] = (uint8_t)g_motion_type;
    58	  value[1] = g_intensity_percent;
    59	  value[2] = g_alert_active ? 1 : 0;
    60	  pthread_mutex_unlock(&g_lock);
    61	
    62	  return bt_gatt_attr_read(conn, attr, buf, len, offset,
    63	                           value, sizeof(value));
    64	}
    65	
    66	static ssize_t velawear_ble_read_threshold(struct bt_conn *conn,
    67	                                           const struct bt_gatt_attr *attr,
    68	                                           void *buf, uint16_t len,
    69	                                           uint16_t offset)
    70	{
    71	  uint16_t seconds;
    72	
    73	  (void)attr;
    74	  pthread_mutex_lock(&g_lock);
    75	  seconds = (uint16_t)g_config->sedentary_threshold_sec;
    76	  pthread_mutex_unlock(&g_lock);
    77	
    78	  return bt_gatt_attr_read(conn, attr, buf, len, offset,
    79	                           &seconds, sizeof(seconds));
    80	}
    81	
    82	static ssize_t velawear_ble_write_threshold(struct bt_conn *conn,
    83	                                            const struct bt_gatt_attr *attr,
    84	                                            const void *buf, uint16_t len,
    85	                                            uint16_t offset, uint8_t flags)
    86	{
    87	  const uint8_t *data = (const uint8_t *)buf;
    88	  uint16_t seconds;
    89	
    90	  (void)conn;
    91	  (void)attr;
    92	  if (buf == NULL || offset != 0 || len != sizeof(uint16_t) ||
    93	      (flags & BT_GATT_WRITE_FLAG_PREPARE) != 0)
    94	    {
    95	      return -EINVAL;
    96	    }
    97	
    98	  seconds = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    99	  if (seconds < 10 || seconds > 3600)
   100	    {
   101	      return -EINVAL;
   102	    }
   103	
   104	  pthread_mutex_lock(&g_lock);
   105	  g_config->sedentary_threshold_sec = seconds;
   106	  pthread_mutex_unlock(&g_lock);
   107	  syslog(LOG_INFO, "[BLE] Sedentary threshold updated: %u s\n",
   108	         (unsigned int)seconds);
   109	  return len;
   110	}
