    85	static int h4_send_data(struct h4_data *h4, uint8_t *buf, size_t count)
    86	{
    87		ssize_t ret, nwritten = 0;
    88	
    89		while (nwritten != count) {
    90			ret = file_write(&h4->filep, buf + nwritten, count - nwritten);
    91			if (ret < 0) {
    92				if (ret == -EAGAIN) {
    93					usleep(500);
    94					continue;
    95				} else {
    96					return ret;
    97				}
    98			}
    99	
   100			nwritten += ret;
   101		}
   102	
   103		return nwritten;
   104	}
