   106	static struct net_buf *get_rx(const uint8_t *buf)
   107	{
   108		bool discardable = false;
   109		k_timeout_t timeout = K_FOREVER;
   110	
   111		switch (buf[0]) {
   112		case BT_HCI_H4_EVT:
   113			if (buf[1] == BT_HCI_EVT_LE_META_EVENT &&
   114			    (buf[3] == BT_HCI_EVT_LE_ADVERTISING_REPORT)) {
   115				discardable = true;
   116				timeout = K_NO_WAIT;
   117			}
   118	
   119			return bt_buf_get_evt(buf[1], discardable, timeout);
   120		case BT_HCI_H4_ACL:
   121			return bt_buf_get_rx(BT_BUF_ACL_IN, K_FOREVER);
   122		case BT_HCI_H4_ISO:
   123			if (IS_ENABLED(CONFIG_BT_ISO)) {
   124				return bt_buf_get_rx(BT_BUF_ISO_IN, K_FOREVER);
   125			}
   126			__fallthrough;
   127		default:
   128			LOG_ERR("Unknown packet type: %u", buf[0]);
   129		}
   130	
   131		return NULL;
   132	}
