   219	static void h4_rx_thread(void *p1, void *p2, void *p3)
   220	{
   221		const struct device *dev = p1;
   222		struct h4_data *h4 = dev->data;
   223	
   224		ARG_UNUSED(p2);
   225		ARG_UNUSED(p3);
   226	
   227		LOG_DBG("started");
   228	
   229		ssize_t frame_size = 0;
   230	
   231		while (1) {
   232			struct net_buf *buf;
   233			size_t buf_tailroom;
   234			size_t buf_add_len;
   235			ssize_t len;
   236			const uint8_t *frame_start = h4->frame;
   237	
   238			LOG_DBG("calling read()");
   239	
   240			len = file_read(&h4->filep, h4->frame + frame_size,
   241					sizeof(h4->frame) - frame_size);
   242			if (len < 0) {
   243				if (len == -EAGAIN) {
   244					usleep(500);
   245					continue;
   246				}
   247	
   248				LOG_ERR("Reading hci failed, err %d", (int)len);
   249				file_close(&h4->filep);
   250				return;
   251			}
   252	
   253			frame_size += len;
   254	
   255			while (frame_size > 0) {
   256				const uint8_t *buf_add;
   257				const uint8_t packet_type = frame_start[0];
   258				const int32_t decoded_len = hci_packet_complete(frame_start, frame_size);
   259	
   260				if (decoded_len == -1) {
   261					LOG_ERR("HCI Packet type is invalid, length could not be decoded");
   262					frame_size = 0; /* Drop buffer */
   263					break;
   264				}
   265	
   266				if (decoded_len == 0) {
   267					if (frame_size == sizeof(h4->frame)) {
   268						LOG_ERR("HCI Packet (%d bytes) is too big for frame (%d "
   269							"bytes)",
   270							decoded_len, sizeof(h4->frame));
   271						frame_size = 0; /* Drop buffer */
   272						break;
   273					}
   274					if (frame_start != h4->frame) {
   275						memmove(h4->frame, frame_start, frame_size);
   276					}
   277					/* Read more */
   278					break;
   279				}
   280	
   281				buf_add = frame_start + sizeof(packet_type);
   282				buf_add_len = decoded_len - sizeof(packet_type);
   283	
   284				buf = get_rx(frame_start);
   285	
   286				btsnoop_log_capture(1, (uint8_t *)frame_start, decoded_len);
   287	
   288				frame_size -= decoded_len;
   289				frame_start += decoded_len;
   290	
   291				if (!buf) {
   292					LOG_DBG("Discard adv report due to insufficient buf");
   293					continue;
   294				}
   295	
   296				buf_tailroom = net_buf_tailroom(buf);
   297				if (buf_tailroom < buf_add_len) {
   298					LOG_ERR("Not enough space in buffer %zu/%zu", buf_add_len,
   299						buf_tailroom);
   300					net_buf_unref(buf);
   301					continue;
   302				}
   303	
   304				net_buf_add_mem(buf, buf_add, buf_add_len);
   305	
   306				LOG_DBG("Calling bt_recv(%p)", buf);
   307	
   308				h4_data_dump("BT RX", packet_type, buf->data, buf_add_len);
   309				h4->recv(dev, buf, h4->hci_data);
   310			}
   311		}
   312	}
