   316	      switch (*(data - H4_HEADER_SIZE))
   317	        {
   318	          case H4_CMD:
   319	            hdrlen = sizeof(struct bt_hci_cmd_hdr_s);
   320	            pktlen = hdr->cmd.param_len;
   321	            type = BT_CMD;
   322	            break;
   323	          case H4_ACL:
   324	            hdrlen = sizeof(struct bt_hci_acl_hdr_s);
   325	            pktlen = hdr->acl.len;
   326	            type = BT_ACL_OUT;
   327	            break;
   328	          case H4_ISO:
   329	            hdrlen = sizeof(struct bt_hci_iso_hdr_s);
   330	            pktlen = hdr->iso.len;
   331	            type = BT_ISO_OUT;
   332	            break;
   333	          default:
   334	            ret = -EINVAL;
   335	            goto err;
   336	        }
   337	
   338	      /* Reassembly is incomplete ? */
   339	
   340	      hdrlen += H4_HEADER_SIZE;
   341	
   342	      if (dev->sendlen < hdrlen)
   343	        {
   344	          goto out;
   345	        }
   346	
   347	      pktlen += hdrlen;
   348	      if (dev->sendlen < pktlen)
   349	        {
   350	          goto out;
   351	        }
   352	
   353	      /* Got the full packet, send out */
   354	
   355	      ret = dev->drv->send(dev->drv, type,
   356	                           data, pktlen - H4_HEADER_SIZE);
   357	      if (ret < 0)
   358	        {
   359	          goto err;
   360	        }
   361	
   362	      dev->sendlen -= pktlen;
   363	      if (dev->sendlen == 0)
   364	        {
   365	          goto out;
   366	        }
   367	
   368	      memmove(data - H4_HEADER_SIZE,
   369	              dev->sendbuf + pktlen, dev->sendlen);
   370	    }
   371	
   372	err:
   373	  dev->sendlen = 0;
   374	out:
   375	  nxmutex_unlock(&dev->sendlock);
   376	  return ret < 0 ? ret : buflen;
   377	}
