   393	static int uart_bth4_poll(FAR struct file *filep, FAR struct pollfd *fds,
   394	                          bool setup)
   395	{
   396	  FAR struct inode *inode = filep->f_inode;
   397	  FAR struct uart_bth4_s *dev = inode->i_private;
   398	  pollevent_t eventset = 0;
   399	  irqstate_t flags;
   400	  int ret = 0;
   401	  int i;
   402	
   403	  flags = spin_lock_irqsave_nopreempt(&dev->lock);
   404	
   405	  if (setup)
   406	    {
   407	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
   408	        {
   409	          /* Find an available slot */
   410	
   411	          if (!dev->fds[i])
   412	            {
   413	              /* Bind the poll structure and this slot */
   414	
   415	              dev->fds[i] = fds;
   416	              fds->priv   = &dev->fds[i];
   417	              break;
   418	            }
   419	        }
   420	
   421	      if (i >= CONFIG_UART_BTH4_NPOLLWAITERS)
   422	        {
   423	          fds->priv = NULL;
   424	          ret = -EBUSY;
   425	        }
   426	
   427	      if (!circbuf_is_empty(&dev->circbuf))
   428	        {
   429	          eventset |= POLLIN;
   430	        }
   431	
   432	      eventset |= POLLOUT;
   433	
   434	      poll_notify(&fds, 1, eventset);
   435	    }
   436	  else if (fds->priv != NULL)
   437	    {
   438	      for (i = 0; i < CONFIG_UART_BTH4_NPOLLWAITERS; i++)
   439	        {
   440	          if (fds == dev->fds[i])
   441	            {
   442	              dev->fds[i] = NULL;
   443	              fds->priv = NULL;
   444	              break;
   445	            }
   446	        }
   447	    }
   448	
   449	  spin_unlock_irqrestore_nopreempt(&dev->lock, flags);
   450	  return ret;
   451	}
