   134	/**
   135	 * @brief Decode the length of an HCI H4 packet and check it's complete
   136	 * @details Decodes packet length according to Bluetooth spec v5.4 Vol 4 Part E
   137	 * @param buf	Pointer to a HCI packet buffer
   138	 * @param buf_len	Bytes available in the buffer
   139	 * @return Length of the complete HCI packet in bytes, -1 if cannot find an HCI
   140	 *         packet, 0 if more data required.
   141	 */
   142	static int32_t hci_packet_complete(const uint8_t *buf, uint16_t buf_len)
   143	{
   144		uint16_t payload_len = 0;
   145		const uint8_t type = buf[0];
   146		uint8_t header_len = sizeof(type);
   147		const uint8_t *hdr = &buf[sizeof(type)];
   148	
   149		switch (type) {
   150		case BT_HCI_H4_CMD: {
   151			if (buf_len < header_len + BT_HCI_CMD_HDR_SIZE) {
   152				return 0;
   153			}
   154			const struct bt_hci_cmd_hdr *cmd = (const struct bt_hci_cmd_hdr *)hdr;
   155	
   156			/* Parameter Total Length */
   157			payload_len = cmd->param_len;
   158			header_len += BT_HCI_CMD_HDR_SIZE;
   159			break;
   160		}
   161		case BT_HCI_H4_ACL: {
   162			if (buf_len < header_len + BT_HCI_ACL_HDR_SIZE) {
   163				return 0;
   164			}
   165			const struct bt_hci_acl_hdr *acl = (const struct bt_hci_acl_hdr *)hdr;
   166	
   167			/* Data Total Length */
   168			payload_len = sys_le16_to_cpu(acl->len);
   169			header_len += BT_HCI_ACL_HDR_SIZE;
   170			break;
   171		}
   172		case BT_HCI_H4_SCO: {
   173			if (buf_len < header_len + BT_HCI_SCO_HDR_SIZE) {
   174				return 0;
   175			}
   176			const struct bt_hci_sco_hdr *sco = (const struct bt_hci_sco_hdr *)hdr;
   177	
   178			/* Data_Total_Length */
   179			payload_len = sco->len;
   180			header_len += BT_HCI_SCO_HDR_SIZE;
   181			break;
   182		}
   183		case BT_HCI_H4_EVT: {
   184			if (buf_len < header_len + BT_HCI_EVT_HDR_SIZE) {
   185				return 0;
   186			}
   187			const struct bt_hci_evt_hdr *evt = (const struct bt_hci_evt_hdr *)hdr;
   188	
   189			/* Parameter Total Length */
   190			payload_len = evt->len;
   314	static int h4_send(const struct device *dev, struct net_buf *buf)
   315	{
   316		struct h4_data *h4 = dev->data;
   317		int len;
   318		int ret;
   319	
   320	
   321		LOG_DBG("buf %p type %u len %u", buf, bt_buf_get_type(buf), buf->len);
   322	
   323		switch (bt_buf_get_type(buf)) {
   324		case BT_BUF_ACL_OUT:
   325			net_buf_push_u8(buf, BT_HCI_H4_ACL);
   326			break;
   327		case BT_BUF_CMD:
   328			net_buf_push_u8(buf, BT_HCI_H4_CMD);
   329			break;
   330		case BT_BUF_ISO_OUT:
   331			if (IS_ENABLED(CONFIG_BT_ISO)) {
   332				net_buf_push_u8(buf, BT_HCI_H4_ISO);
   333				break;
   334			}
   335			__fallthrough;
   336		default:
   337			LOG_ERR("Unknown buffer type");
   338			return -EINVAL;
   339		}
   340	
   341		h4_data_dump("BT TX", buf->data[0], buf->data + 1, buf->len - 1);
   342	
   343		pthread_mutex_lock(&h4->mutex);
   344		len = buf->len;
   345		btsnoop_log_capture(0, buf->data, buf->len);
   346		ret = h4_send_data(h4, buf->data, buf->len);
   347		if (ret != len) {
   348			ret = -EINVAL;
   349		}
   350	
   351		net_buf_unref(buf);
   352		pthread_mutex_unlock(&h4->mutex);
   353	
   354		return ret < 0 ? ret : 0;
   355	}
