   357	static int h4_open(const struct device *dev, bt_hci_recv_t recv, void *hci_data)
   358	{
   359		int ret;
   360		struct h4_data *h4 = dev->data;
   361		char dev_name[32];
   362	
   363		if (dev->name == NULL) {
   364			LOG_ERR("No device name");
   365			return -EINVAL;
   366		}
   367	
   368		ret = snprintf(dev_name, sizeof(dev_name), "%s", dev->name);
   369		if (ret < 0 || ret >= sizeof(dev_name)) {
   370			LOG_ERR("dev_name:%s snprintf failed, ret %d, ", dev->name, ret);
   371			return -EINVAL;
   372		}
   373	
   374		ret = file_open(&h4->filep, dev_name, O_RDWR | O_BINARY);
   375		if (ret < 0) {
   376			goto bail;
   377		}
   378	
   379		LOG_DBG("H4: %s opened", dev_name);
   380	
   381		ret = (int)k_thread_create(&h4->rx_thread_data, h4->rx_thread_stack,
   382					   K_THREAD_STACK_SIZEOF(h4->rx_thread_stack), h4_rx_thread, (void *)dev, NULL,
   383					   NULL, K_PRIO_COOP(CONFIG_BT_RX_PRIO), 0, K_NO_WAIT);
   384	
   385		if (ret < 0) {
   386			goto bail;
   387		} else {
   388			ret = 0;
   389		}
   390	
   391		h4->recv = recv;
   392		h4->hci_data = hci_data;
   393	
   394		ret = snprintf(dev_name, sizeof(dev_name), "BT Driver %s", dev->name);
   395		if (ret < 0 || ret >= sizeof(dev_name)) {
   396			LOG_ERR("dev_name:%s snprintf failed, ret %d, ", dev->name, ret);
   397			return -EINVAL;
   398		}
   399	
   400		k_thread_name_set(&h4->rx_thread_data, dev_name);
   401		LOG_DBG("returning");
   402	
   403		return 0;
   404	
   405	bail:
   406		file_close(&h4->filep);
   407	
   408		return ret;
   409	}
