   355	static int sf32lb52_bt_wait_tx_idle(struct circular_buf *tx_ring)
   356	{
   357	  uint32_t start_time = HAL_GetTick();
   358	  uint32_t tick_count = 0;
   359	  uint32_t rd_ptr = 0;
   360	  uint32_t wr_ptr = 0;
   361	
   362	  while (sf32lb52_bt_tx_pending(tx_ring, &rd_ptr, &wr_ptr) > 0)
   363	    {
   364	      sf32lb52_bt_trigger_tx();
   365	
   366	      if (HAL_GetTick() != start_time)
   367	        {
   368	          tick_count++;
   369	          start_time = HAL_GetTick();
   370	        }
   371	
   372	      if (tick_count >= 100)
   373	        {
   374	          syslog(LOG_ERR,
   375	                 "sf32lb52 bt tx busy: rd=%08lx wr=%08lx\n",
   376	                 (unsigned long)rd_ptr,
   377	                 (unsigned long)wr_ptr);
   378	          return -ETIMEDOUT;
   379	        }
   380	
   381	      usleep(1000);
   382	    }
   383	
   384	  return OK;
   385	}
