  1010	 *
  1011	 * Description:
  1012	 *   This is a kernel thread that handles sending of commands.
  1013	 *
  1014	 * Input Parameters:
  1015	 *   Standard kernel thread arguments
  1016	 *
  1017	 * Returned Value:
  1018	 *   Doesn't normally return.
  1019	 *
  1020	 ****************************************************************************/
  1021	
  1022	static int hci_tx_kthread(int argc, FAR char *argv[])
  1023	{
  1024	  FAR struct bt_driver_s *btdev = g_btdev.btdev;
  1025	  int ret;
  1026	
  1027	  wlinfo("started\n");
  1028	
  1029	  for (; g_btdev.tx_status == OK; )
  1030	    {
  1031	      FAR struct bt_buf_s *buf;
  1032	
  1033	      /* Wait until ncmd > 0 */
  1034	
  1035	      ret = nxsem_wait_uninterruptible(&g_btdev.ncmd_sem);
  1036	      if (ret < 0)
  1037	        {
  1038	          wlerr("nxsem_wait_uninterruptible() failed: %d\n", ret);
  1039	          return EXIT_FAILURE;
  1040	        }
  1041	
  1042	      /* Get next command - wait if necessary */
  1043	
  1044	      buf = NULL;
  1045	      ret = bt_queue_receive(&g_btdev.tx_queue, &buf);
  1046	      DEBUGASSERT(ret >= 0 && buf != NULL);
  1047	      UNUSED(ret);
  1048	
  1049	      g_btdev.ncmd = 0;
  1050	
  1051	      /* Clear out any existing sent command */
  1052	
  1053	      if (g_btdev.sent_cmd)
  1054	        {
  1055	          wlerr("ERROR:  Uncleared pending sent_cmd\n");
  1056	          bt_buf_release(g_btdev.sent_cmd);
  1057	          g_btdev.sent_cmd = NULL;
  1058	        }
  1059	
  1060	      /* Allow transmission if module is connected. */
  1061	
  1062	      if (g_btdev.tx_status == OK)
  1063	        {
  1064	          g_btdev.sent_cmd = bt_buf_addref(buf);
  1065	
  1066	          wlinfo("Sending command %04x buf %p to driver\n",
  1067	                 buf->u.hci.opcode, buf);
  1068	
  1069	          bt_send(btdev, buf);
  1070	        }
  1071	
  1072	      bt_buf_release(buf);
  1073	    }
  1074	
  1075	  /* Acknowledge the termination request. */
  1076	
  1077	  g_btdev.tx_status = ESHUTDOWN;
  1078	  return EXIT_SUCCESS;
  1079	}
