   723	int sf32lb52_bt_controller_enable(void)
   724	{
   725	  int ret;
   726	
   727	
   728	  if (g_sf32lb52_bt_status == SF32LB52_BT_STATUS_ENABLED)
   729	    {
   730	      return OK;
   731	    }
   732	
   733	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_INITED)
   734	    {
   735	      return -EPERM;
   736	    }
   737	
   738	  sf32lb52_bt_prepare_stack_nvds();
   739	  HAL_LCPU_ASSERT_INFO_clear();
   740	
   741	  ret = lcpu_power_on();
   742	  if (ret != 0)
   743	    {
   744	      return -EIO;
   745	    }
   746	
   747	  /* The L2H_MAILBOX (0x40002000) is on the LPSYS APB bus.  Its CxIER
   748	   * register is only writable when the LPSYS bus bridge is active.
   749	   * Wake the LCPU first so the bus bridge is powered, THEN open the
   750	   * IPC queue (which writes CxIER to unmask the mailbox RX interrupt).
   751	   * The SDK reference ipc_hw_enable_interrupt2() has the same
   752	   * HAL_HPAON_WakeCore() before the UNMASK call.
   753	   */
   754	
   755	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
   756	  g_sf32lb52_bt_env.wake_held = true;
   757	
   758	  usleep(500000);
   759	
   760	  ret = ipc_queue_open(g_sf32lb52_bt_env.ipc_port);
   761	  if (ret < 0)
   762	    {
   763	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
   764	      g_sf32lb52_bt_env.wake_held = false;
   765	      return ret;
   766	    }
   767	
   768	  /* Flush H2L TX ring to SRAM immediately after ipc_queue_open so
   769	   * LCPU sees the reset indices (read_idx=write_idx=0) before it
   770	   * tries to process any stale data from a previous session.
   771	   */
   772	  up_clean_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
   773	                  (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
   774	                  SF32LB52_BT_TX_BUF_SIZE);
   775	  __DSB();
   776	
   777	  /* After every lcpu_power_on(), LCPU resets its TX ring write pointer
   778	   * (write_idx_mirror) to 0 and writes its own boot responses into the
   779	   * ring.  HCPU's read pointer (read_idx_mirror) may still hold the
   780	   * non-zero value from the previous session -- dirty in DCache or
   781	   * stored in SRAM.  If we do not synchronise them:
   782	   *
   783	   *   circular_buf_data_len() = wrap(write_idx - read_idx)
   784	   *
   785	   * returns a large garbage value, and LCPU's fresh boot events
   786	   * plus ring garbage all replay as "new" HCI responses.  These
   787	   * ghost events are consumed by the host as replies to real commands,
   788	   * so HCI_Reset (0x0c01) is never actually executed by the controller,
   789	   * and bt_le_adv_start later gets "Command Disallowed" (0x07).
   790	   *
   791	   * Fix: flush DCache to write back any dirty read_idx and to load
   792	   * LCPU's current write_idx from SRAM, then advance read_idx to
   793	   * write_idx (discard ALL pending LCPU boot data), then clean the
   794	   * DCache so LCPU sees the updated read pointer in SRAM.
   795	   */
   796	
   797	  {
   798	    struct circular_buf *rx_ring =
   799	        (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
   800	
   801	    ret = sf32lb52_bt_wait_rx_ring_ready();
   802	    if (ret < 0)
   803	      {
   804	        syslog(LOG_ERR, "sf32lb52 rx ring not ready: %d\n", ret);
   805	        ipc_queue_close(g_sf32lb52_bt_env.ipc_port);
   806	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
   807	        g_sf32lb52_bt_env.wake_held = false;
   808	        return ret;
   809	      }
   810	
   811	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
   812	    g_sf32lb52_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
   813	
   814	    up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   815	                    (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   816	                    sizeof(*rx_ring));
   817	    __DSB();
   818	  }
   819	
   820	  {
   821	    volatile MAILBOX_CH_TypeDef *l2h = L2H_MAILBOX;
   822	    uint32_t nvic_bit = (1UL << (LCPU2HCPU_IRQn & 0x1F));
   823	    uint32_t nvic_en  = NVIC->ISER[LCPU2HCPU_IRQn >> 5];
   824	
   825	    (void)l2h;
   826	    (void)nvic_bit;
   827	    (void)nvic_en;
   828	  }
   829	
   830	  g_sf32lb52_bt_env.queue_open = true;
   831	  g_sf32lb52_bt_status = SF32LB52_BT_STATUS_ENABLED;
   832	
   833	  return OK;
   834	}
