   886	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
   887	{
   888	  struct circular_buf *tx_ring =
   889	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
   890	  uint32_t start_time;
   891	  uint32_t tick_count;
   892	  size_t written;
   893	  size_t remaining;
   894	  size_t offset;
   895	  size_t chunk;
   896	  size_t chunks;
   897	  uint32_t wr_ptr;
   898	  int ret;
   899	
   900	
   901	  if (data == NULL || len == 0)
   902	    {
   903	      return -EINVAL;
   904	    }
   905	
   906	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
   907	      !g_sf32lb52_bt_env.queue_open)
   908	    {
   909	      return -ENODEV;
   910	    }
   911	
   912	  offset = 0;
   913	  remaining = len;
   914	  start_time = HAL_GetTick();
   915	  tick_count = 0;
   916	  chunks = 0;
   917	  wr_ptr = 0;
   918	
   919	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
   920	  if (ret < 0)
   921	    {
   922	      return ret;
   923	    }
   924	
   925	  while (remaining > 0)
   926	    {
   927	      irqstate_t flags;
   928	
   929	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
   930	
   931	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
   932	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
   933	                           sizeof(*tx_ring));
   934	
   935	      flags = enter_critical_section();
   936	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
   937	      leave_critical_section(flags);
   938	
   939	      if (written == 0)
   940	        {
   941	          if (HAL_GetTick() != start_time)
   942	            {
   943	              tick_count++;
   944	              start_time = HAL_GetTick();
   945	            }
   946	
   947	          if (tick_count >= 10)
   948	            {
   949	              syslog(LOG_ERR,
   950	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
   951	                     (unsigned long)remaining);
   952	              return -ETIMEDOUT;
   953	            }
   954	
   955	          continue;
   956	        }
   957	
   958	      offset += written;
   959	      remaining -= written;
   960	
   961	      __DSB();
   962	      wr_ptr = tx_ring->write_idx_mirror;
   963	      sf32lb52_bt_trigger_tx();
   964	      chunks++;
   965	    }
   966	
   967	#if SF32LB52_BT_TRACE
   968	  syslog(LOG_INFO,
   969	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
   970	         len,

